WITH ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY city ORDER BY rating NULLS LAST, id) AS latest_rank FROM suppliers) t WHERE latest_rank = 1) SELECT id, supplier_name, country, city, rating, latest_rank, CASE WHEN supplier_name RLIKE '^(Pacific Wholesale|Tokyo Traders)$' THEN 'OTHER_ZONE' WHEN supplier_name RLIKE '^(Siam Parts Co|Global Supply)$' THEN 'CORE' ELSE 'PRIORITY' END AS supplier_name_zone FROM ranked;
